t.script:

// Gallery functionality
function setMainImage(busId, thumbnailElement) {
    const mainImg = document.getElementById('mainImg' + busId);
    if (mainImg && thumbnailElement) {
        mainImg.src = thumbnailElement.src;
        mainImg.alt = thumbnailElement.alt;

        // Update active thumbnail
        const thumbnailContainer = thumbnailElement.closest('.thumbnail-gallery');
        if (thumbnailContainer) {
            thumbnailContainer.querySelectorAll('.thumbnail-img').forEach(img => {
                img.classList.remove('active');
            });
            thumbnailElement.classList.add('active');
        }
    }
}

function changeImage(busId, direction) {
    const thumbnailContainer = document.querySelector('[data-category] img[id="mainImg' + busId + '"]');
    if (!thumbnailContainer) return;

    const galleryContainer = thumbnailContainer.closest('.fleet-card').querySelector('.thumbnail-gallery');
    if (!galleryContainer) return;

    const thumbnails = galleryContainer.querySelectorAll('.thumbnail-img');
    if (thumbnails.length === 0) return;

    const activeIndex = Array.from(thumbnails).findIndex(img => img.classList.contains('active'));
    let newIndex = activeIndex + direction;

    if (newIndex >= thumbnails.length) newIndex = 0;
    if (newIndex < 0) newIndex = thumbnails.length - 1;

    setMainImage(busId, thumbnails[newIndex]);
}

// Features Modal functionality
function showFeatures(busId) {
    const featuresData = document.querySelector('.bus-features-data[data-bus-id="' + busId + '"]');
    const modalBody = document.getElementById('featuresModalBody');

    if (featuresData && modalBody) {
        const features = featuresData.querySelectorAll('.feature-item');

        if (features.length > 0) {
            let featuresHTML = '<div class="features-list">';
            features.forEach(feature => {
                featuresHTML += '<div class="feature-item">' + feature.innerHTML + '</div>';
            });
            featuresHTML += '</div>';
            modalBody.innerHTML = featuresHTML;
        } else {
            modalBody.innerHTML = '<p class="text-muted text-center py-3">No special features available for this bus.</p>';
        }

        // Wait for Bootstrap to be available, then show modal
        if (typeof bootstrap !== 'undefined') {
            const modal = new bootstrap.Modal(document.getElementById('featuresModal'));
            modal.show();
        } else {
            console.error('Bootstrap is not loaded yet');
            // Fallback: You could manually show/hide the modal here
            alert('Feature details will be shown in a popup once the page fully loads.');
        }
    }
}

// Share Bus functionality
function shareBus(busId, busName, dailyRate) {
    // Create clean URL slug from bus name
    const busSlug = busName.toLowerCase()
        .replace(/[^a-z0-9\s-]/g, '') // Remove special characters
        .replace(/\s+/g, '-') // Replace spaces with hyphens
        .replace(/-+/g, '-') // Replace multiple hyphens with single
        .trim();

    // Create share URL with bus name
    const currentUrl = window.location.href.split('#')[0]; // Remove any existing hash
    const busUrl = currentUrl + '#' + busSlug;


    // Check if Web Share API is supported
    if (navigator.share && navigator.canShare(shareData)) {
        navigator.share(shareData)
            .then(() => console.log('Successfully shared'))
            .catch((error) => console.log('Error sharing', error));
    } else {
        // Fallback: Copy just the URL to clipboard and show options
        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(busUrl).then(() => {
                showShareFallback(shareData, busName, true);
            }).catch(() => {
                showShareFallback(shareData, busName, false);
            });
        } else {
            showShareFallback(shareData, busName, false);
        }
    }
}

function showShareFallback(shareData, busName, copiedToClipboard) {
    // Create modal content for share options
    const modalBody = document.getElementById('featuresModalBody');
    const modalTitle = document.getElementById('featuresModalLabel');

    modalTitle.innerHTML = '<i class="fas fa-share-alt me-2"></i>Share ' + busName;

    // Create clean share text for social media
    const cleanShareText = shareData.text + ' - ' + shareData.url;

    let shareOptions = `
        <div class="share-options text-center">
            ${copiedToClipboard ?
                '<div class="alert alert-success mb-3"><i class="fas fa-check-circle me-2"></i>Link copied to clipboard!</div>' :
                '<div class="alert alert-info mb-3"><i class="fas fa-info-circle me-2"></i>Click the links below to share:</div>'
            }

            <div class="share-buttons d-grid gap-2 mb-3">
                <a href="https://wa.me/?text=${encodeURIComponent(cleanShareText)}"
                   target="_blank"
                   class="btn btn-success">
                    <i class="fab fa-whatsapp me-2"></i>Share on WhatsApp
                </a>
                <a href="https://t.me/share/url?url=${encodeURIComponent(shareData.url)}&text=${encodeURIComponent(shareData.text)}"
                   target="_blank"
                   class="btn btn-primary">
                    <i class="fab fa-telegram me-2"></i>Share on Telegram
                </a>
                <a href="mailto:?subject=${encodeURIComponent(shareData.title)}&body=${encodeURIComponent(cleanShareText)}"
                   class="btn btn-secondary">
                    <i class="fas fa-envelope me-2"></i>Share via Email
                </a>
            </div>

            <div class="share-text">
                <label class="form-label fw-bold">Or copy this link:</label>
                <textarea class="form-control" rows="2" readonly onclick="this.select()">${shareData.url}</textarea>
                <button class="btn btn-outline-primary btn-sm mt-2" onclick="copyShareText(this)">
                    <i class="fas fa-copy me-1"></i>Copy Link
                </button>
            </div>
        </div>
    `;

    modalBody.innerHTML = shareOptions;

    // Show modal
    if (typeof bootstrap !== 'undefined') {
        const modal = new bootstrap.Modal(document.getElementById('featuresModal'));
        modal.show();
    }
}

function copyShareText(button) {
    const textarea = button.previousElementSibling;
    textarea.select();
    document.execCommand('copy');

    // Show feedback
    const originalText = button.innerHTML;
    button.innerHTML = '<i class="fas fa-check me-1"></i>Copied!';
    button.classList.remove('btn-outline-primary');
    button.classList.add('btn-success');

    setTimeout(() => {
        button.innerHTML = originalText;
        button.classList.remove('btn-success');
        button.classList.add('btn-outline-primary');
    }, 2000);
}

// Filter functionality
document.addEventListener('DOMContentLoaded', function() {
    const filterButtons = document.querySelectorAll('.filter-btn');
    const fleetCards = document.querySelectorAll('[data-category]');
    const noResults = document.getElementById('noResults');

    filterButtons.forEach(button => {
        button.addEventListener('click', function() {
            const category = this.getAttribute('data-category');

            // Update active button
            filterButtons.forEach(btn => btn.classList.remove('active'));
            this.classList.add('active');

            // Filter cards
            let visibleCount = 0;
            fleetCards.forEach(card => {
                if (category === 'all' || card.getAttribute('data-category') === category) {
                    card.style.display = 'block';
                    visibleCount++;
                } else {
                    card.style.display = 'none';
                }
            });

            // Show/hide no results message
            if (visibleCount === 0) {
                noResults.style.display = 'block';
            } else {
                noResults.style.display = 'none';
            }
        });
    });

    // Initialize first thumbnail as active
    document.querySelectorAll('.thumbnail-gallery').forEach(gallery => {
        const firstThumbnail = gallery.querySelector('.thumbnail-img');
        if (firstThumbnail) {
            firstThumbnail.classList.add('active');
        }
    });
});

// Image Preview functionality
let currentZoom = 1;
let isDragging = false;
let startX = 0;
let startY = 0;
let translateX = 0;
let translateY = 0;

function openImagePreview(imageSrc, busName) {
    const modal = document.getElementById('imagePreviewModal');
    const previewImage = document.getElementById('previewImage');
    const titleElement = document.getElementById('imagePreviewTitle');

    // Set image and title
    previewImage.src = imageSrc;
    titleElement.textContent = busName || 'Bus Image';

    // Reset zoom and position
    currentZoom = 1;
    translateX = 0;
    translateY = 0;
    updateImageTransform();

    // Show modal
    if (typeof bootstrap !== 'undefined') {
        const imageModal = new bootstrap.Modal(modal);
        imageModal.show();
    }
}

function updateImageTransform() {
    const previewImage = document.getElementById('previewImage');
    const container = previewImage.parentElement;

    previewImage.style.transform = `translate(${translateX}px, ${translateY}px) scale(${currentZoom})`;

    // Update zoom level display
    document.getElementById('zoomLevel').textContent = Math.round(currentZoom * 100) + '%';

    // Update cursor based on zoom level
    if (currentZoom > 1) {
        container.style.cursor = 'grab';
    } else {
        container.style.cursor = 'zoom-in';
    }
}

function zoomIn() {
    if (currentZoom < 3) {
        currentZoom += 0.25;
        updateImageTransform();
    }
}

function zoomOut() {
    if (currentZoom > 0.5) {
        currentZoom -= 0.25;
        // Reset position if zooming out beyond 1x
        if (currentZoom <= 1) {
            translateX = 0;
            translateY = 0;
        }
        updateImageTransform();
    }
}

function resetZoom() {
    currentZoom = 1;
    translateX = 0;
    translateY = 0;
    updateImageTransform();
}

// Add event listeners for image preview modal
document.addEventListener('DOMContentLoaded', function() {
    const previewModal = document.getElementById('imagePreviewModal');
    const previewImage = document.getElementById('previewImage');
    const container = previewImage.parentElement;

    // Mouse wheel zoom
    container.addEventListener('wheel', function(e) {
        e.preventDefault();
        if (e.deltaY < 0) {
            zoomIn();
        } else {
            zoomOut();
        }
    });

    // Click to zoom
    container.addEventListener('click', function(e) {
        if (currentZoom === 1) {
            zoomIn();
        }
    });

    // Drag functionality for zoomed images
    container.addEventListener('mousedown', function(e) {
        if (currentZoom > 1) {
            isDragging = true;
            startX = e.clientX - translateX;
            startY = e.clientY - translateY;
            container.style.cursor = 'grabbing';
            e.preventDefault();
        }
    });

    document.addEventListener('mousemove', function(e) {
        if (isDragging && currentZoom > 1) {
            translateX = e.clientX - startX;
            translateY = e.clientY - startY;
            updateImageTransform();
        }
    });

    document.addEventListener('mouseup', function() {
        if (isDragging) {
            isDragging = false;
            if (currentZoom > 1) {
                container.style.cursor = 'grab';
            }
        }
    });

    // Keyboard shortcuts
    document.addEventListener('keydown', function(e) {
        if (previewModal.classList.contains('show')) {
            switch(e.key) {
                case '+':
                case '=':
                    e.preventDefault();
                    zoomIn();
                    break;
                case '-':
                    e.preventDefault();
                    zoomOut();
                    break;
                case '0':
                    e.preventDefault();
                    resetZoom();
                    break;
                case 'Escape':
                    bootstrap.Modal.getInstance(previewModal).hide();
                    break;
            }
        }
    });
});
